13	function createUtilitySql(url: string) {
14	  return postgres(url, { max: 1, onnotice: () => {} });
15	}
16	
17	function isSafeIdentifier(value: string): boolean {
18	  return /^[A-Za-z_][A-Za-z0-9_]*$/.test(value);
19	}
20	
21	function quoteIdentifier(value: string): string {
22	  if (!isSafeIdentifier(value)) throw new Error(`Unsafe SQL identifier: ${value}`);
23	  return `"${value.replaceAll("\"", "\"\"")}"`;
24	}
25	
26	function quoteLiteral(value: string): string {
27	  return `'${value.replaceAll("'", "''")}'`;
28	}
29	
30	function splitMigrationStatements(content: string): string[] {
31	  return content
32	    .split("--> statement-breakpoint")
33	    .map((statement) => statement.trim())
34	    .filter((statement) => statement.length > 0);
35	}
36	
37	export type MigrationState =
38	  | { status: "upToDate"; tableCount: number; availableMigrations: string[]; appliedMigrations: string[] }
39	  | {
40	      status: "needsMigrations";
41	      tableCount: number;
42	      availableMigrations: string[];
43	      appliedMigrations: string[];
44	      pendingMigrations: string[];
45	      reason: "no-migration-journal-empty-db" | "no-migration-journal-non-empty-db" | "pending-migrations";
46	    };
